ALTER TABLE public.tenant_settings ADD COLUMN numbering_scope text NOT NULL DEFAULT 'client' CHECK (numbering_scope IN ('global','client'));
ALTER TABLE public.clients ADD COLUMN code text;
DO $$ DECLARE c record; proposed text; base text; suffix integer; BEGIN FOR c IN SELECT * FROM public.clients ORDER BY tenant_id,created_at,id LOOP SELECT (regexp_match(o.invoice_number,'^[0-9]+/[^/]+/INV/([A-Za-z0-9]{1,8})/'))[1] INTO proposed FROM public.orders o WHERE o.tenant_id=c.tenant_id AND (o.client_id=c.id OR lower(btrim(o.client_name))=lower(btrim(c.name))) AND o.invoice_number ~ '^[0-9]+/[^/]+/INV/[A-Za-z0-9]{1,8}/' ORDER BY o.created_at DESC LIMIT 1; base:=COALESCE(upper(proposed),NULLIF(left(regexp_replace(upper(split_part(btrim(c.name),' ',1)),'[^A-Z]','','g'),6),''),'CLIENT'); proposed:=base;suffix:=0; WHILE EXISTS(SELECT 1 FROM public.clients x WHERE x.tenant_id=c.tenant_id AND upper(x.code)=proposed AND x.id<>c.id) LOOP suffix:=suffix+1;proposed:=left(base,8-length(suffix::text))||suffix; END LOOP; UPDATE public.clients SET code=proposed WHERE id=c.id; END LOOP; END $$;
ALTER TABLE public.clients ADD CONSTRAINT clients_code_valid CHECK(code IS NULL OR code ~ '^[A-Z0-9]{1,8}$');
CREATE UNIQUE INDEX clients_tenant_code_unique ON public.clients(tenant_id,upper(code)) WHERE code IS NOT NULL;
ALTER TABLE public.shipments ADD COLUMN stored_by_member_id uuid, ADD COLUMN delivery_by_member_id uuid;
ALTER TABLE public.shipments ADD CONSTRAINT shipments_stored_member_fk FOREIGN KEY(tenant_id,stored_by_member_id) REFERENCES public.team_members(tenant_id,id) ON DELETE SET NULL (stored_by_member_id), ADD CONSTRAINT shipments_delivery_member_fk FOREIGN KEY(tenant_id,delivery_by_member_id) REFERENCES public.team_members(tenant_id,id) ON DELETE SET NULL (delivery_by_member_id);
UPDATE public.shipments SET stored_by=NULL WHERE stored_by ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$';
UPDATE public.shipments SET delivery_by=NULL WHERE delivery_by ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$';
UPDATE public.shipments s SET stored_by_member_id=(SELECT m.id FROM public.team_members m WHERE m.tenant_id=s.tenant_id AND lower(btrim(m.name))=lower(btrim(s.stored_by)) AND m.deleted_at IS NULL ORDER BY m.created_at,m.id LIMIT 1),delivery_by_member_id=(SELECT m.id FROM public.team_members m WHERE m.tenant_id=s.tenant_id AND lower(btrim(m.name))=lower(btrim(s.delivery_by)) AND m.deleted_at IS NULL ORDER BY m.created_at,m.id LIMIT 1);
CREATE FUNCTION public.sales_sequence_value(p_number text) RETURNS bigint LANGUAGE plpgsql IMMUTABLE SET search_path=public AS $$ DECLARE raw text; BEGIN IF p_number ~ '^[0-9]+/' THEN raw:=split_part(p_number,'/',1); ELSIF p_number ~ '^(INV|PO|QUO)/[^/]+/[0-9]{4}/[0-9]{2}/[0-9]+$' THEN raw:=(regexp_match(p_number,'/([0-9]+)$'))[1]; END IF; IF raw IS NULL OR length(raw)>18 THEN RETURN NULL; END IF; RETURN raw::bigint; END $$;
REVOKE ALL ON FUNCTION public.sales_sequence_value(text) FROM PUBLIC,anon,authenticated;
CREATE FUNCTION public.sales_client_code(p_tenant uuid,p_client text,p_client_id uuid) RETURNS text LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE result text; BEGIN IF p_client_id IS NOT NULL THEN SELECT code INTO result FROM public.clients WHERE tenant_id=p_tenant AND id=p_client_id AND deleted_at IS NULL; IF NOT FOUND THEN RAISE EXCEPTION 'Client tidak berizin'; END IF; ELSE SELECT code INTO result FROM public.clients WHERE tenant_id=p_tenant AND deleted_at IS NULL AND lower(btrim(name))=lower(btrim(p_client)) ORDER BY created_at,id LIMIT 1; END IF; RETURN COALESCE(result,NULLIF(left(regexp_replace(upper(btrim(p_client)),'[^A-Z0-9]','','g'),8),'')); END $$;
REVOKE ALL ON FUNCTION public.sales_client_code(uuid,text,uuid) FROM PUBLIC,anon,authenticated;
CREATE FUNCTION public.next_sales_number(p_client text,p_type text,p_date date,p_client_id uuid) RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE tid uuid:=public.active_tenant_id(); code text; counter_code text; n bigint; fmt text; scope text; BEGIN IF p_type NOT IN ('order','invoice','quotation') OR NOT public.can_access_tenant_module(tid,CASE WHEN p_type='quotation' THEN 'quotations' ELSE 'orders' END) THEN RAISE EXCEPTION 'Modul tidak berizin'; END IF; code:=public.sales_client_code(tid,p_client,p_client_id); IF code IS NULL OR p_date IS NULL THEN RAISE EXCEPTION 'Client dan tanggal wajib'; END IF; SELECT numbering_scope,CASE WHEN numbering_scope='global' THEN COALESCE(sales_numbering->>p_type,doc_numbering->>p_type) ELSE COALESCE(NULLIF(doc_numbering->>p_type,'{SEQ}/SDY/INV/{CLIENT}/{MM}{YYYY}'),sales_numbering->>p_type) END INTO scope,fmt FROM public.tenant_settings WHERE tenant_id=tid; IF fmt IS NULL OR (position('{SEQ}' in fmt)=0 AND position('{urut}' in fmt)=0) THEN RAISE EXCEPTION 'Format nomor harus memuat {SEQ} atau {urut}'; END IF; counter_code:=CASE WHEN scope='global' THEN '*' ELSE code END; INSERT INTO public.document_sequences(tenant_id,client_code,document_type,sequence) VALUES(tid,counter_code,p_type,1) ON CONFLICT(tenant_id,client_code,document_type) DO UPDATE SET sequence=GREATEST(public.document_sequences.sequence,0)+1 RETURNING sequence INTO n; RETURN replace(replace(replace(replace(replace(replace(fmt,'{CLIENT}',code),'{KODE_CLIENT}',code),'{YYYY}',to_char(p_date,'YYYY')),'{MM}',to_char(p_date,'MM')),'{SEQ}',n::text),'{urut}',n::text); END $$;
REVOKE ALL ON FUNCTION public.next_sales_number(text,text,date,uuid) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.next_sales_number(text,text,date,uuid) TO service_role;
CREATE OR REPLACE FUNCTION public.next_sales_number(p_client text,p_type text,p_date date) RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN RETURN public.next_sales_number(p_client,p_type,p_date,NULL); END $$;
CREATE OR REPLACE FUNCTION public.track_sales_sequence() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE code text; scope text; pair record; n bigint; BEGIN SELECT numbering_scope INTO scope FROM public.tenant_settings WHERE tenant_id=NEW.tenant_id; code:=CASE WHEN scope='global' THEN '*' ELSE public.sales_client_code(NEW.tenant_id,NEW.client_name,NEW.client_id) END; FOR pair IN SELECT * FROM (VALUES(CASE WHEN TG_TABLE_NAME='orders' THEN 'invoice' ELSE 'quotation' END,CASE WHEN TG_TABLE_NAME='orders' THEN to_jsonb(NEW)->>'invoice_number' ELSE to_jsonb(NEW)->>'quotation_number' END),('order',CASE WHEN TG_TABLE_NAME='orders' THEN to_jsonb(NEW)->>'order_number' END),('order',CASE WHEN TG_TABLE_NAME='orders' THEN to_jsonb(NEW)->>'po_number' END)) AS v(typ,num) LOOP n:=public.sales_sequence_value(pair.num); IF n IS NOT NULL AND code IS NOT NULL THEN INSERT INTO public.document_sequences(tenant_id,client_code,document_type,sequence) VALUES(NEW.tenant_id,code,pair.typ,n) ON CONFLICT(tenant_id,client_code,document_type) DO UPDATE SET sequence=GREATEST(public.document_sequences.sequence,EXCLUDED.sequence); END IF; END LOOP; RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.track_sales_sequence() FROM PUBLIC,anon,authenticated;
DO $$ DECLARE def text; BEGIN def:=pg_get_functiondef('public.save_sales_document(text,uuid,jsonb,jsonb)'::regprocedure); def:=replace(def,'public.next_sales_number(p_doc->>''client_name'',''order'',d)','public.next_sales_number(p_doc->>''client_name'',''order'',d,NULLIF(p_doc->>''client_id'','''')::uuid)'); def:=replace(def,'public.next_sales_number(p_doc->>''client_name'',''quotation'',d)','public.next_sales_number(p_doc->>''client_name'',''quotation'',d,NULLIF(p_doc->>''client_id'','''')::uuid)'); EXECUTE def; def:=pg_get_functiondef('public.issue_invoice(uuid)'::regprocedure); def:=replace(def,'public.next_sales_number(o.client_name,''invoice'',o.invoice_date)','public.next_sales_number(o.client_name,''invoice'',(now() AT TIME ZONE ''Asia/Jakarta'')::date,o.client_id)'); EXECUTE def; def:=pg_get_functiondef('public.create_shipment_atomic(uuid)'::regprocedure); def:=replace(def,'o.created_by,o.created_by','NULL,NULL'); EXECUTE def; END $$;
CREATE FUNCTION public.shipment_team_options() RETURNS TABLE(id uuid,name text) LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.can_access('shipments') THEN RAISE EXCEPTION 'Pengiriman tidak berizin'; END IF; RETURN QUERY SELECT m.id,m.name FROM public.team_members m WHERE m.tenant_id=public.active_tenant_id() AND m.is_active AND m.deleted_at IS NULL ORDER BY m.name,m.id; END $$;
CREATE FUNCTION public.assign_shipment_team(p_shipment_id uuid,p_stored_by uuid,p_delivery_by uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE tid uuid:=public.active_tenant_id(); stored text; delivery text; BEGIN IF NOT public.can_access_tenant_module(tid,'shipments') THEN RAISE EXCEPTION 'Pengiriman tidak berizin'; END IF; PERFORM 1 FROM public.shipments WHERE id=p_shipment_id AND tenant_id=tid AND deleted_at IS NULL FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Pengiriman tidak ditemukan'; END IF; IF p_stored_by IS NOT NULL THEN SELECT name INTO stored FROM public.team_members WHERE id=p_stored_by AND tenant_id=tid AND is_active AND deleted_at IS NULL FOR SHARE; IF NOT FOUND THEN RAISE EXCEPTION 'Anggota tim penyimpan tidak berizin atau tidak aktif'; END IF; END IF; IF p_delivery_by IS NOT NULL THEN SELECT name INTO delivery FROM public.team_members WHERE id=p_delivery_by AND tenant_id=tid AND is_active AND deleted_at IS NULL FOR SHARE; IF NOT FOUND THEN RAISE EXCEPTION 'Anggota tim pengirim tidak berizin atau tidak aktif'; END IF; END IF; UPDATE public.shipments SET stored_by_member_id=p_stored_by,delivery_by_member_id=p_delivery_by,stored_by=stored,delivery_by=delivery WHERE id=p_shipment_id AND tenant_id=tid; INSERT INTO public.audit_logs(tenant_id,actor_id,action,entity_type,entity_id,diff) VALUES(tid,auth.uid(),'assign_shipment_team','shipments',p_shipment_id,jsonb_build_object('stored_by_member_id',p_stored_by,'delivery_by_member_id',p_delivery_by,'stored_by',stored,'delivery_by',delivery)); END $$;
REVOKE ALL ON FUNCTION public.shipment_team_options(),public.assign_shipment_team(uuid,uuid,uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.shipment_team_options(),public.assign_shipment_team(uuid,uuid,uuid) TO authenticated,service_role;